{
  "findings": [
    {
      "check_id": "CKV_GCP_62",
      "title": "Bucket should log access",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not have logging enabled, which makes it difficult to track access and detect unauthorized access attempts."
    },
    {
      "check_id": "CKV_GCP_29",
      "title": "Ensure that Cloud Storage buckets have uniform bucket-level access enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Uniform bucket-level access is not enabled, which can lead to inconsistent permissions and potential misconfigurations."
    },
    {
      "check_id": "CKV_GCP_114",
      "title": "Ensure public access prevention is enforced on Cloud Storage bucket",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Public access prevention is not enforced, which could allow unintended public access to the bucket."
    }
  ],
  "patched_code": "resource \"google_storage_bucket\" \"compliance_storage\" {\n  name     = \"${var.project_id}-digital-asset-trading-platform-compliance\"\n  location = var.region\n\n  versioning {\n    enabled = true\n  }\n\n  lifecycle_rule {\n    condition {\n      age = 2555\n    }\n    action {\n      type = \"Delete\"\n    }\n  }\n\n  logging {\n    log_bucket        = \"${var.project_id}-logs\"\n    log_object_prefix = \"compliance-storage\"\n  }\n\n  uniform_bucket_level_access = true\n\n  public_access_prevention = \"enforced\"\n}",
  "fix_summary": "Enabled logging for the bucket to track access, enforced uniform bucket-level access to simplify permissions management, and enforced public access prevention to avoid unintended public exposure."
}
